using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "AreaPurifyEffectBasedCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Any/AreaPurifyEffectBasedCustomDescription", order = 0)]
public class AreaPurifyEffectBasedCustomDescription : CustomBattleActionDescription
{
	private const string effectTheyHaveID = "EffectTheyHave";

	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		AreaPurifyEffectBasedAction areaPurifyEffectBasedAction = battleAction as AreaPurifyEffectBasedAction;
		string text = "";
		if (areaPurifyEffectBasedAction.ApplyEffectBeforePurify)
		{
			text = areaPurifyEffectBasedAction.EffectAction.GetActionDescription(areaPurifyEffectBasedAction.EffectAmount) + "\n";
		}
		string arg = Smart.Format(base.localizationManager.GetLocalizedString("EffectTheyHave"), areaPurifyEffectBasedAction.Effect.GetEffectName());
		string text2 = "";
		text2 = areaPurifyEffectBasedAction.PurifyAction.GetActionDescription(GetAmountWithoutEquation(amountModified), GetBonusAmountWithoutEquation(amountModified));
		text2 = text2.RemoveLastIfNotJapaneseNorKoreanNorTraditionalChinese();
		string localizedForEach = base.localizationManager.GetLocalizedForEach();
		string text3 = "";
		if (areaPurifyEffectBasedAction.CleansingConflagration)
		{
			text3 = GetRawLocalizedDescription(battleAction);
		}
		else
		{
			Smart.Format(base.localizationManager.GetLocalizedString("EffectTheyHave"), areaPurifyEffectBasedAction.Effect.GetEffectName());
			string text4 = "";
			text4 = areaPurifyEffectBasedAction.SecondaryPurifyAction.GetActionDescription(GetAmountWithoutEquation(amountModified), GetBonusAmountWithoutEquation(amountModified));
			text4 = text4.RemoveLastIfNotJapaneseNorKoreanNorTraditionalChinese();
			text3 = Smart.Format(localizedForEach, text4, base.localizationManager.GetLocalizedEffectSentinelsHaveFormatted(areaPurifyEffectBasedAction.Effect));
		}
		return text + Smart.Format(localizedForEach, text2, arg) + "\n" + text3;
	}
}
